import { test } from 'node:test';
import assert from 'node:assert/strict';
import { functionEnvironment } from '../lib/deploy/stack.js';
import { start } from '../src/server.js';
import { sign } from '../src/hooks/signing.js';

// Every place the app runs has to hand the start-up its signing key, as a reference to where infra
// registers the value (lib/deploy/README.md) and never as the value itself (docs/hook-signing.md).

const REGISTERED = 'k-registered-by-infra';
const body = '{"room":"A-3"}';

function assertStartsAndTakesSignedCalls(env) {
  assert.equal(start(env).receive(body, sign(body, REGISTERED)).status, 202);
}

test('cloud function: the signing key is read from the parameter store', () => {
  const env = functionEnvironment();
  assert.equal(env.NODE_ENV, 'production');
  assert.deepEqual(Object.keys(env.HOOK_SIGNING_KEY ?? {}), ['fromParameter']);
  assert.match(env.HOOK_SIGNING_KEY.fromParameter, /^\/booking-hooks\/prod\/[a-z0-9-]+$/);

  // What the deploy does: replace each reference with the value registered under its path.
  const store = { [env.HOOK_SIGNING_KEY.fromParameter]: REGISTERED };
  const resolved = Object.fromEntries(
    Object.entries(env).map(([name, v]) => [name, typeof v === 'string' ? v : store[v.fromParameter]]),
  );
  assertStartsAndTakesSignedCalls(resolved);
});

