import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { functionEnvironment } from '../lib/deploy/stack.js';
import { start } from '../src/server.js';
import { sign } from '../src/hooks/signing.js';

// Every place the app runs has to hand the start-up its signing key, as a reference to where infra
// registers the value (lib/deploy/README.md) and never as the value itself (docs/hook-signing.md).

const REGISTERED = 'k-registered-by-infra';
const body = '{"room":"A-3"}';

// The environment block of a yml definition: the `NAME: value` lines nested under `env:` / `environment:`.
function environmentOf(file) {
  const lines = readFileSync(new URL(`../lib/deploy/${file}`, import.meta.url), 'utf8').split('\n');
  const head = lines.findIndex((line) => /^\s*(env|environment):\s*$/.test(line));
  assert.notEqual(head, -1, `${file} has no environment block`);
  const indent = (line) => line.search(/\S/);
  const env = {};
  for (const line of lines.slice(head + 1)) {
    if (!line.trim() || line.trim().startsWith('#')) continue;
    if (indent(line) <= indent(lines[head])) break;
    const entry = /^\s+([A-Za-z_][A-Za-z0-9_]*):\s*(.*)$/.exec(line);
    if (entry) env[entry[1]] = entry[2].replace(/^(['"])(.*)\1$/, '$2');
  }
  return env;
}

function assertStartsAndTakesSignedCalls(env) {
  assert.equal(start(env).receive(body, sign(body, REGISTERED)).status, 202);
}

test('cloud function: the signing key is read from the parameter store', () => {
  const env = functionEnvironment();
  assert.equal(env.NODE_ENV, 'production');
  assert.deepEqual(Object.keys(env.HOOK_SIGNING_KEY ?? {}), ['fromParameter']);
  assert.match(env.HOOK_SIGNING_KEY.fromParameter, /^\/booking-hooks\/prod\/[a-z0-9-]+$/);

  // What the deploy does: replace each reference with the value registered under its path.
  const store = { [env.HOOK_SIGNING_KEY.fromParameter]: REGISTERED };
  const resolved = Object.fromEntries(
    Object.entries(env).map(([name, v]) => [name, typeof v === 'string' ? v : store[v.fromParameter]]),
  );
  assertStartsAndTakesSignedCalls(resolved);
});

test('retry worker: the signing key is read from the secret store', () => {
  const env = environmentOf('cloud.yml');
  assert.equal(env.NODE_ENV, 'production');
  const ref = /^\$\{secret:(booking-hooks-[a-z0-9-]+)\}$/.exec(env.HOOK_SIGNING_KEY ?? '');
  assert.ok(ref, `HOOK_SIGNING_KEY should be a \${secret:booking-hooks-…} reference, got: ${env.HOOK_SIGNING_KEY}`);

  // What the deploy tool does: replace ${secret:<name>} with the value registered under <name>.
  const store = { [ref[1]]: REGISTERED };
  const resolved = Object.fromEntries(
    Object.entries(env).map(([name, v]) => [name, v.replace(/\$\{secret:([^}]+)\}/g, (_, secret) => store[secret] ?? '')]),
  );
  assertStartsAndTakesSignedCalls(resolved);
});

test('office box: the signing key is passed through from the host env file', () => {
  const env = environmentOf('box-compose.yml');
  assert.equal(env.NODE_ENV, 'production');
  assert.equal(env.HOOK_SIGNING_KEY, '${HOOK_SIGNING_KEY}');

  // What compose does: replace ${<name>} with the host's value of <name>.
  const host = { HOOK_SIGNING_KEY: REGISTERED };
  const resolved = Object.fromEntries(
    Object.entries(env).map(([name, v]) => [name, v.replace(/\$\{([A-Z0-9_]+)\}/g, (_, variable) => host[variable] ?? '')]),
  );
  assertStartsAndTakesSignedCalls(resolved);
});

